var t=`1281-madongo-dumplings`;var n=`world-1281`;var o=`VC`;var a=`central-america-caribbean`;var s=8;var r=62;var l={en:`Madongo Dumplings`,ua:`Кнедлики мадонго`};var d={en:`Madongo Dumplings is a dish from Saint Vincent and the Grenadines featuring arrowroot tuber, cassava root, coconut milk. This home-sized recipe records each ingredient at the step where it is used. Arrowroot tuber provides a home approximation; the exact traditional madongo starch and binding vary by island.`,ua:`Кнедлики мадонго, страва кухні країни Сент-Вінсент і Гренадини з такими основними складниками: кореневище маранти, маніок, кокосове молоко. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Бульби маранти дають домашнє наближення; традиційний крохмаль і зв’язувальні компоненти мадонго різняться.`};var g=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:14,i:[[`arrowroot-tuber`,600,`g`],[`cassava-root`,310,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`coconut-milk`,200,`ml`],[`table-salt`,7,`g`]]},{en:`Shape the arrowroot-cassava mixture into compact dumplings with damp hands; no filling is needed.`,ua:`Вологими руками сформуйте компактні кнедлики із суміші маранти й маніоку; начинка не потрібна.`,t:[`pressing`,`rolling-out-dough`],m:13,i:[]},{en:`Cook dumplings in batches in gently boiling salted water for about 23 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 23 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:23,i:[[`water`,1250,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,45,`g`]]}];var u={slug:t,id:n,country:`VC`,region:a,servings:8,minutes:62,title:l,text:d,steps:g};export{o as country,u as default,n as id,r as minutes,a as region,s as servings,t as slug,g as steps,d as text,l as title};